WITH flagged AS (SELECT *, CASE WHEN started_at - LAG(started_at) OVER (PARTITION BY device ORDER BY started_at, id) > INTERVAL '30' DAY THEN 1 ELSE 0 END AS is_new_session FROM sessions), islands AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY device ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM flagged) SELECT browser, CASE WHEN is_new_session >= 1 THEN 'HIGH' ELSE 'LOW' END AS is_new_session_tier, ROUND(AVG(is_new_session), 2) AS avg_is_new_session, ROUND(SUM(is_new_session) / NULLIF(COUNT(CASE WHEN browser = 'Safari' THEN 1 END), 0), 2) AS is_new_session_per_safari, PERCENTILE_APPROX(is_new_session, 0.5) AS is_new_session_p50 FROM islands GROUP BY browser, CASE WHEN is_new_session >= 1 THEN 'HIGH' ELSE 'LOW' END ORDER BY avg_is_new_session
